import{_ as o,o as i,c as r,a2 as l}from"./chunks/framework.vLhlLNVn.js";const _=JSON.parse('{"title":"✨ 功能特性","description":"","frontmatter":{},"headers":[],"relativePath":"features.md","filePath":"features.md","lastUpdated":1795655946000}'),n={name:"features.md"};function s(e,t,a,g,p,c){return i(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="✨-功能特性" tabindex="-1">✨ 功能特性 <a class="header-anchor" href="#✨-功能特性" aria-label="Permalink to &quot;✨ 功能特性&quot;">​</a></h1><ul><li><strong>DLNA (UPnP AV)</strong>：把小爱音箱注册为可投送的媒体渲染器，支持网易云音乐、QQ 音乐等 App 投送。</li><li><strong>AirPlay</strong>：作为 AirPlay 接收器，支持 iPhone / Mac 音频投送（FairPlay / HAP 配对）。 <ul><li><strong>音频流格式自适应</strong>：带屏型号（触屏音箱 / 智能家庭屏，如 X08C / LX04 / X10A）默认经 ffmpeg 转 MP3 下发（其 ROM 播放器不接受 WAV 流），其余型号（含 music-api 白名单中的非触屏型号，它们收到 MP3 地址不会来拉流）保持 WAV 零编码延迟；服务设置中可手动切换（自动 / WAV / MP3）。设备上显式开启「兼容模式」可改走 <code>play_by_url</code> 作为兜底。</li></ul></li><li><strong>Spotify 畅联 (Spotify Connect)</strong>： <ul><li><strong>官方客户端支持</strong>：内置 Spotify 官方 Soloist 引擎，小爱音箱可作为 Spotify Connect 设备被手机、平板及桌面端 App 发现并投送播放。</li><li><strong>支持跨网音乐控制</strong>：区别于 DLNA / AirPlay 严格受限于同一局域网组播发现，Spotify Connect 基于云端会话同步；配对后手机无论处于移动蜂窝网络（4G/5G）还是异地 Wi-Fi，只要登录同一 Spotify 账号，均可随时随地远程向音箱投送、切歌与调音。</li><li><strong>自动二进制管理</strong>：Soloist 官方二进制在首次启用时按架构自动从 Spotify CDN 下载至数据目录，避免内置分发；支持 90 天构建到期自动拉取新版热重启，并支持 Web 后台一键检测更新。</li><li><strong>活动设备门控</strong>：精确追踪 Connect 设备状态，仅当本机为当前活跃播放设备时才向音箱推流，避免其他端播放时误唤醒；播放转移或登出时即刻停止推流。</li><li><strong>线性无损调音</strong>：开播初始音量遵循后台配置并将音箱硬件拉满，由 Spotify App 音量滑杆进行 1:1 软件线性调音；暂停或断开后硬件音量自动还原为默认值，防止闲置爆音。</li><li><strong>触屏歌词与封面</strong>：自动提取曲目元数据并智能匹配小米曲库，带屏小爱音箱可同步呈现滚动歌词与高清专辑封面。</li></ul></li><li><strong>小米云控制</strong>：通过小米账号 API 控制音箱播放、音量、状态查询。</li><li><strong>触屏封面定制</strong>：在「触屏显示」设置中通过下拉选择小米云封面（audioID），带屏/触屏音箱走小米云播放时显示对应封面与歌词，保存后重新投送即可生效。</li><li><strong>Web 管理后台</strong>：登录鉴权（含登录失败限速、登录日志）、总览面板（WebSocket 实时推送当前曲目与播放源，并显示 AirPlay RTP/解码/音箱拉流诊断）、设备管理、播放控制、账号配置、系统设置、运行日志（可下载完整日志文件）。</li><li><strong>通知推送</strong>：登录过期等事件通过飞书 / WxPusher / Telegram 推送提醒（Telegram 支持自建反代）。</li><li><strong>主题与更新</strong>：亮色 / 暗色 / 跟随系统三态主题（默认跟随系统），面板内检查 GitHub 最新版本。</li><li><strong>热重启子服务</strong>：保存配置后热重启 DLNA/AirPlay/Spotify 接收器，无需重启整个容器或后台进程。</li></ul>',2)])])}const u=o(n,[["render",s]]);export{_ as __pageData,u as default};
